import random
from typing import List, Optional

class Node:
    __slots__ = ['val', 'count', 'weight', 'size', 'left', 'right']
    def __init__(self, val):
        self.val = val
        self.count = 1
        self.weight = random.random()
        self.size = 1
        self.left = self.right = None

def touch(root: Optional[Node]) -> None:
    if root:
        root.size = root.count + size(root.left) + size(root.right)

def size(root: Optional[Node]) -> int:
    return root.size if root else 0

def insert(root: Optional[Node], val: int) -> Optional[Node]:
    t1, r, t2 = split(root, val)
    if not r:
        r = Node(val)
    else:
        r.count += 1
        touch(r)
    t2 = join(r, t2)
    return join(t1, t2)

def remove(root: Optional[Node], val: int) -> Optional[Node]:
    t1, r, t2 = split(root, val)
    if r:
        r.count -= 1
        if r.count:
            touch(r)
        t2 = join(r, t2)
    return join(t1, t2)

def split(root: Optional[Node], val: int) -> tuple[Optional[Node], Optional[Node], Optional[Node]]:
    if not root:
        return None, None, None
    if root.val < val:
        a, b, c = split(root.right, val)
        root.right = a
        touch(root)
        return root, b, c
    if root.val > val:
        a, b, c = split(root.left, val)
        root.left = c
        touch(root)
        return a, b, root
    a, c = root.left, root.right
    root.left = root.right = None
    touch(root)
    return a, root, c

def join(t1: Optional[Node], t2: Optional[Node]) -> Optional[Node]:
    if not t1: return t2
    if not t2: return t1
    if t1.weight < t2.weight:
        t1.right = join(t1.right, t2)
        touch(t1)
        return t1
    else:
        t2.left = join(t1, t2.left)
        touch(t2)
        return t2

def get(root: Optional[Node], index: int) -> int:
    left = size(root.left)
    if left < index <= left + root.count:
        return root.val
    if left + root.count < index:
        return get(root.right, index - root.count)
    return get(root.left, index)

